// Presentation preferences only. Weather data, native legend positions and
// legacy visibility remain owned by their existing modules.
export const LEGEND_HUB_KEY='gewitterradar:legend-hub:v1';
export const LEGEND_IDS=Object.freeze(['precipitation','wind','temperature','advection','synoptic','other']);
export const LEGEND_OPTIONS=Object.freeze({presentation:['premium','compact'],orientation:['horizontal','vertical'],size:['S','M','L','XL'],density:['coarse','medium','detailed'],style:['clean','precision','thermometer'],material:['brass','platinum','gold','silver','black'],labels:['before','inside','after'],ticks:['before','inside','after'],foreground:['auto','white','black','ice','mint','champagne','gold'],mode:['inherit','on','off']});
const select=(v,a,f)=>a.includes(v)?v:f,clamp=(v,a,b,f)=>Number.isFinite(v)?Math.max(a,Math.min(b,v)):f;
export const position=(v,f={x:.08,y:.3})=>({x:clamp(v?.x,0,1,f.x),y:clamp(v?.y,0,1,f.y)});
export function normalizeLegendOptions(v={}){const defaults={presentation:'premium',orientation:'horizontal',size:'M',density:'medium',style:'clean',material:'platinum',labels:'after',ticks:'inside',foreground:'auto',mode:'inherit'};return {...Object.fromEntries(Object.entries(defaults).map(([k,f])=>[k,select(v?.[k],LEGEND_OPTIONS[k],f)])),autoInvert:v?.autoInvert!==false,shadow:v?.shadow!==false,outline:v?.outline!==false};}
export function normalizeLegendHub(v={}){const slots=Array.isArray(v?.slots)?v.slots:['precipitation','wind','temperature','synoptic'];return {schema:1,icon:v?.icon===2?2:1,direction:select(v?.direction,['dynamic','left','right','up','down','horizontal','vertical'],'dynamic'),autoClose:v?.autoClose!==false,glassTransparency:clamp(v?.glassTransparency,0,100,65),position:position(v?.position),slots:slots.slice(0,12).map(id=>LEGEND_IDS.includes(id)?id:null).concat(slots.length?[]:[null]),legends:Object.fromEntries(LEGEND_IDS.map(id=>[id,normalizeLegendOptions(v?.legends?.[id])])),extraPositions:Object.fromEntries(['synoptic','other'].map(id=>[id,position(v?.extraPositions?.[id],{x:id==='synoptic'?1:0,y:.12})])),extraUi:Object.fromEntries(['synoptic','other'].map(id=>[id,{view:v?.extraUi?.[id]?.view==='classes'?'classes':'bar',minimized:v?.extraUi?.[id]?.minimized===true,explanation:v?.extraUi?.[id]?.explanation===true}]))};}
export function assignLegendSlot(config,index,id){const c=normalizeLegendHub(config);if(index<0||index>=c.slots.length||id!==null&&!LEGEND_IDS.includes(id))return c;const old=c.slots.indexOf(id);if(id&&old>=0&&old!==index)[c.slots[old],c.slots[index]]=[c.slots[index],id];else c.slots[index]=id;return c;}
